// ================================================================
// STEP 1: Get your FREE rss2json API key (takes 2 minutes)
// 1. Go to: https://rss2json.com
// 2. Click 'Sign Up Free' (top right)
// 3. Create account with any email
// 4. After login — your API Key is shown on the Dashboard page
// 5. Copy it and paste it below
// ================================================================
const RSS2JSON_KEY = 'PASTE_YOUR_KEY_HERE';

// ================================================================
// YouTube Channels — verified channel IDs (all confirmed working)
// ================================================================
const channels = [
  { id: 'UCsBjURrPoezykLs9EqgamOA', name: 'Fireship',       cat: 'Tech/Dev' },
  { id: 'UCHlNU7kIZhRgSbhHvFoy72w', name: 'Hugging Face',   cat: 'AI Tools' },
  { id: 'UCbfYPyITQ-7l4upoX8nvctg', name: 'Two Min Papers', cat: 'AI Research' },
  { id: 'UCNJ1Ymd5yFuUPtn21xtRbbw', name: 'AI Explained',   cat: 'AI News' },
  { id: 'UCSHZKyawb77ixDdsGog4iWA', name: 'Lex Fridman',    cat: 'Tech/AI/Biz' },
  { id: 'UCxIJaCMEptJjxmmQgGFsnCg', name: 'Y Combinator',   cat: 'Startup' },
  { id: 'UCnxrdFPXJMeHru_b4Q_vTPQ', name: 'NetworkChuck',   cat: 'Networking' },
  { id: 'UCZHmQk67mSJgfCCTn7xBfew', name: 'Yannic Kilcher', cat: 'AI/ML' },
  { id: 'UCBJycsmduvYEL83R_U4JriQ', name: 'MKBHD',          cat: 'Tech Reviews' },
  { id: 'UC9-y-6csu5WGm29I7JiwpnA', name: 'Computerphile',  cat: 'CS/Tech' },
  { id: 'UCCjyq_K1Xwfg8Lndy7lKMpA', name: 'TechCrunch YT',  cat: 'Tech News' },
  { id: 'UCESLZhusAkFfsNsApnjF_Cg', name: 'All-In Podcast', cat: 'B2B/Startup' }
];

const CLAUDE_KEY   = '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';
const CLAUDE_MODEL = 'claude-sonnet-4-6';
const DIGEST_EMAIL = 'countrycoveinc@gmail.com';

const cutoff = new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString();
const today  = new Date().toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric', timeZone:'America/New_York' });

const hasKey = RSS2JSON_KEY && RSS2JSON_KEY.length > 10 && RSS2JSON_KEY !== 'PASTE_YOUR_KEY_HERE';
console.log('[Config] channels:' + channels.length + ' | key:' + (hasKey ? 'YES' : 'NO - get free key at rss2json.com') + ' | cutoff:' + cutoff);

return [{ json: { channels, RSS2JSON_KEY, hasKey, CLAUDE_KEY, CLAUDE_MODEL, DIGEST_EMAIL, cutoff, today } }];

const cfg = $('Config: Keys + Channels').item.json;

// Get both RSS feeds
let tcXml = '', hnXml = '';
try {
  const tcRaw = $('HTTP: TechCrunch RSS').item.json;
  tcXml = (typeof tcRaw === 'string') ? tcRaw : (tcRaw.data || tcRaw.body || '');
} catch(e) {}
try {
  const hnRaw = $input.item.json;
  hnXml = (typeof hnRaw === 'string') ? hnRaw : (hnRaw.data || hnRaw.body || '');
} catch(e) {}

function parseRSS(xml, source, limit) {
  const items = [];
  let pos = 0;
  while (items.length < (limit || 10)) {
    const s = xml.indexOf('<item>', pos);
    if (s < 0) break;
    const e = xml.indexOf('</item>', s);
    if (e < 0) break;
    const b = xml.slice(s + 6, e);
    pos = e + 7;
    function gv(tag) {
      const open = '<' + tag + '>', close = '</' + tag + '>';
      const si = b.indexOf(open), ei = b.indexOf(close);
      if (si < 0 || ei < 0) return '';
      let v = b.slice(si + open.length, ei);
      const cs = v.indexOf('<![CDATA['), ce = v.indexOf(']]>');
      if (cs >= 0 && ce > cs) v = v.slice(cs + 9, ce);
      return v.replace(/<[^>]+>/g,'').trim();
    }
    const title = gv('title');
    if (!title || title.length < 4) continue;
    const ls = b.indexOf('<link>'), le = b.indexOf('</link>');
    const link = (ls >= 0 && le >= 0) ? b.slice(ls + 6, le).trim() : gv('guid');
    const desc = gv('description').slice(0, 250);
    items.push({ source, category: 'Trending', title, url: link, description: desc });
  }
  return items;
}

const tcItems = parseRSS(tcXml, 'TechCrunch', 12);
const hnItems = parseRSS(hnXml, 'Hacker News', 10);
const trendingItems = tcItems.concat(hnItems);
console.log('[News] TC:' + tcItems.length + ' HN:' + hnItems.length + ' total:' + trendingItems.length);

// Build channel items for the split loop
return cfg.channels.map(function(ch) {
  const keyPart = cfg.hasKey ? '&api_key=' + cfg.RSS2JSON_KEY + '&count=15' : '&count=10';
  const r2jUrl  = 'https://api.rss2json.com/v1/api.json?rss_url=' + encodeURIComponent('https://www.youtube.com/feeds/videos.xml?channel_id=' + ch.id) + keyPart;
  return {
    json: {
      channelId:   ch.id,
      channelName: ch.name,
      channelCat:  ch.cat,
      r2jUrl,
      cutoff:      cfg.cutoff,
      today:       cfg.today,
      CLAUDE_KEY:  cfg.CLAUDE_KEY,
      CLAUDE_MODEL:cfg.CLAUDE_MODEL,
      DIGEST_EMAIL:cfg.DIGEST_EMAIL,
      trendingItems
    }
  };
});

// Get channel context from Split node
let chInfo = {};
try { chInfo = $('Split: One Channel at a Time').item.json || {}; } catch(e) {}
const chName        = chInfo.channelName || 'Unknown';
const chCat         = chInfo.channelCat  || 'General';
const cutoff        = new Date(chInfo.cutoff || (Date.now() - 7*24*3600*1000));
const trendingItems = Array.isArray(chInfo.trendingItems) ? chInfo.trendingItems : [];
const meta = { today: chInfo.today, CLAUDE_KEY: chInfo.CLAUDE_KEY, CLAUDE_MODEL: chInfo.CLAUDE_MODEL, DIGEST_EMAIL: chInfo.DIGEST_EMAIL };

const EMPTY = [{ json: Object.assign({ channelName: chName, category: chCat, videos: [], trendingItems }, meta) }];

// Get rss2json response from HTTP node
let raw = {};
try { raw = $input.item.json || {}; } catch(e) { console.log('[' + chName + '] input error'); return EMPTY; }

// Debug: log what we actually received
const rawType  = typeof raw;
const rawKeys  = (rawType === 'object' && raw !== null) ? Object.keys(raw).join(',') : rawType;
const rawStr   = rawType === 'string' ? raw.slice(0,100) : JSON.stringify(raw).slice(0,150);
console.log('[' + chName + '] raw type=' + rawType + ' keys=' + rawKeys + ' | ' + rawStr);

// Unwrap any n8n wrapping
let d = raw;
if (rawType === 'string') { try { d = JSON.parse(raw); } catch(e2) { d = {}; } }
else if (raw && raw.body) { try { d = JSON.parse(raw.body); } catch(e2) { d = raw; } }
else if (raw && raw.json) { d = raw.json; }

const status = (d && d.status) || '';
const items  = (d && Array.isArray(d.items)) ? d.items : [];
console.log('[' + chName + '] status=' + status + ' items=' + items.length + (d && d.message ? ' msg=' + d.message : ''));

if (status !== 'ok' || items.length === 0) {
  console.log('[' + chName + '] SKIP — no valid rss2json response');
  return EMPTY;
}

// Parse videos
const videos = [];
for (var i = 0; i < items.length; i++) {
  try {
    const item = items[i];
    const pub  = item.pubDate ? item.pubDate.replace(' ', 'T') : '';
    if (pub) {
      const pubDate = new Date(pub);
      if (!isNaN(pubDate.getTime()) && pubDate < cutoff) continue;
    }
    const url = item.link || '';
    if (!url) continue;
    const vi    = url.indexOf('v=');
    const vidId = vi >= 0 ? url.slice(vi + 2, vi + 13) : null;
    if (!vidId || vidId.length !== 11) continue;
    const title = (item.title || '').replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&quot;/g,'"').trim();
    if (!title) continue;
    const desc  = (item.description || '').replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').replace(/&#39;/g,"'").slice(0, 500).trim();
    const thumb = item.thumbnail || ('https://i.ytimg.com/vi/' + vidId + '/hqdefault.jpg');
    videos.push({ videoId: vidId, title, url, published: item.pubDate || '', description: desc, thumbnail: thumb, views: 0, channel: chName, category: chCat });
  } catch(ex) { continue; }
}
console.log('[' + chName + '] => ' + videos.length + ' videos within 7d');
return [{ json: Object.assign({ channelName: chName, category: chCat, videos, trendingItems }, meta) }];

const allChannels = $input.item.json.allChannels || [];

let allVideos = [], trendingItems = [];
let today = '', CLAUDE_KEY = '', CLAUDE_MODEL = '', DIGEST_EMAIL = '';

for (var i = 0; i < allChannels.length; i++) {
  const ch = allChannels[i];
  if (Array.isArray(ch.videos)) allVideos = allVideos.concat(ch.videos);
  if (Array.isArray(ch.trendingItems) && ch.trendingItems.length > trendingItems.length) trendingItems = ch.trendingItems;
  if (ch.today)        today        = ch.today;
  if (ch.CLAUDE_KEY)   CLAUDE_KEY   = ch.CLAUDE_KEY;
  if (ch.CLAUDE_MODEL) CLAUDE_MODEL = ch.CLAUDE_MODEL;
  if (ch.DIGEST_EMAIL) DIGEST_EMAIL = ch.DIGEST_EMAIL;
}

// Deduplicate + sort by date
const seen = new Set();
allVideos = allVideos
  .filter(function(v) { if (seen.has(v.videoId)) return false; seen.add(v.videoId); return true; })
  .sort(function(a,b) { return new Date(b.published || 0) - new Date(a.published || 0); });

console.log('[Build] ' + allVideos.length + ' videos | ' + trendingItems.length + ' trending');

// Always have content — even if YouTube fails, TechCrunch+HN trending is used
const videoSection = allVideos.length > 0
  ? allVideos.map(function(v, i) {
      return (i+1) + '. [' + v.category + '] ' + v.channel + ': "' + v.title + '"\nLink: ' + v.url + '\nDescription: ' + (v.description || '(see link)').slice(0, 350);
    }).join('\n\n')
  : 'No YouTube videos found this week. Focus digest on the trending news items below.';

const trendingSection = trendingItems.length > 0
  ? trendingItems.map(function(t) { return '[' + t.source + '] ' + t.title + (t.url ? ' — ' + t.url : '') + (t.description ? '\n' + t.description.slice(0,150) : ''); }).join('\n\n')
  : 'No trending news available.';

const prompt = 'You are a sharp AI + Tech + Business curator. Today is ' + today + '.\n\n'
  + '== TRENDING NEWS (TechCrunch + Hacker News, last 24h) ==\n' + trendingSection + '\n\n'
  + '== YOUTUBE VIDEOS THIS WEEK (' + allVideos.length + ' videos from 12 tracked channels) ==\n' + videoSection + '\n\n'
  + '== YOUR TASK ==\n'
  + 'Write a high-value daily digest. Use EXACTLY these headers (ALL CAPS):\n\n'
  + 'HEADLINE OF THE DAY\nOne bold sentence — the single most important story right now.\n\n'
  + 'TOP VIDEOS THIS WEEK\nFor each video: title | channel | 2-sentence summary | link\n\n'
  + 'KEY INSIGHTS\n5 specific bullets drawn directly from the video descriptions or news items. Use real details, numbers, or concepts mentioned.\n\n'
  + 'AI & AUTOMATION HIGHLIGHTS\n3 bullets on the most important AI/automation developments.\n\n'
  + 'BUSINESS & STARTUP SIGNALS\n2 bullets — key business/SaaS/startup signals from this week.\n\n'
  + 'TRENDING IN TECH\n3 stories from TechCrunch or HN with one-line commentary on why each matters.\n\n'
  + 'WHAT TO BUILD THIS WEEK\n1 concrete, specific product or automation idea directly inspired by this week content.\n\n'
  + 'QUOTE OF THE DAY\nOne memorable insight (cite the source).\n\n'
  + 'Tone: direct, intelligent, no filler. Plain text only — NO markdown or asterisks.';

const claudeRequest = JSON.stringify({ model: CLAUDE_MODEL || 'claude-sonnet-4-6', max_tokens: 4000, messages: [{ role: 'user', content: prompt }] });
return [{ json: { allVideos, trendingItems, totalVideos: allVideos.length, today, CLAUDE_KEY, CLAUDE_MODEL, DIGEST_EMAIL, claudeRequest } }];

const prev       = $('Code: Build Claude Request').item.json;
const claudeResp = $input.item.json;

let digestText = 'Digest generation failed.';
try { const t = claudeResp?.content?.[0]?.text; if (t && t.length > 50) digestText = t; } catch(e) {}

const allVideos     = prev.allVideos     || [];
const trendingItems = prev.trendingItems || [];

function timeAgo(s) {
  if (!s) return '';
  const d = Math.floor((Date.now() - new Date(s.replace(' ','T')).getTime()) / 86400000);
  return d <= 0 ? 'Today' : d + 'd ago';
}

// Video cards
const videoCards = allVideos.slice(0,6).map(function(v, i) {
  return '<div style="border:1px solid #1f2937;border-radius:10px;overflow:hidden;margin-bottom:14px;background:#111827;">'
    + '<table cellpadding="0" cellspacing="0" width="100%"><tr>'
    + '<td width="150" valign="top"><a href="' + v.url + '" target="_blank"><img src="' + (v.thumbnail||'') + '" width="150" height="85" alt="" style="display:block;"/></a></td>'
    + '<td valign="top" style="padding:10px 12px;">'
    + '<p style="margin:0 0 3px;font-size:10px;color:#6b7280;">#' + (i+1) + ' <span style="background:#1d4ed8;color:#bfdbfe;padding:1px 6px;border-radius:8px;font-size:9px;font-weight:700;">' + (v.category||'') + '</span> ' + timeAgo(v.published) + '</p>'
    + '<a href="' + v.url + '" style="text-decoration:none;"><p style="margin:0 0 3px;color:#f9fafb;font-size:13px;font-weight:700;line-height:1.4;">' + (v.title||'') + '</p></a>'
    + '<p style="margin:0;color:#9ca3af;font-size:11px;">&#128250; ' + (v.channel||'') + '</p></td></tr></table></div>';
}).join('');

// Trending pills
const trendHtml = trendingItems.slice(0,8).map(function(t) {
  const col = t.source === 'Hacker News' ? '#f97316' : '#a78bfa';
  return '<p style="margin:0 0 6px;font-size:12px;color:#d1d5db;border-left:3px solid ' + col + ';padding-left:8px;">'
    + '<a href="' + (t.url||'#') + '" style="color:' + col + ';text-decoration:none;font-weight:600;">' + (t.title||'') + '</a> <span style="color:#6b7280;font-size:10px;">[' + (t.source||'') + ']</span></p>';
}).join('');

// Section parser
const HEADS = ['HEADLINE OF THE DAY','TOP VIDEOS THIS WEEK','KEY INSIGHTS','AI & AUTOMATION HIGHLIGHTS','BUSINESS & STARTUP SIGNALS','TRENDING IN TECH','WHAT TO BUILD THIS WEEK','QUOTE OF THE DAY'];
function extract(text, h) {
  const i = text.indexOf(h); if (i < 0) return '';
  const start = i + h.length; let end = text.length;
  HEADS.forEach(function(s) { if (s===h) return; const ni=text.indexOf(s,start); if (ni>0&&ni<end) end=ni; });
  return text.slice(start,end).trim();
}
function block(h, content, color) {
  if (!content) return '';
  const lines = content.split('\n').filter(function(l){return l.trim().length>0;});
  const body  = lines.map(function(l) {
    const linked = l.replace(/(https?:\/\/[^\s]+)/g,'<a href="$1" style="color:#818cf8;">$1</a>');
    if (/^[•\-*]|^\d+\./.test(l.trim())) return '<p style="margin:4px 0 4px 8px;color:#d1d5db;font-size:13px;">' + linked + '</p>';
    return '<p style="margin:4px 0;color:#e5e7eb;font-size:13px;line-height:1.65;">' + linked + '</p>';
  }).join('');
  return '<div style="margin-bottom:22px;"><p style="margin:0 0 8px;font-size:10px;font-weight:800;color:' + color + ';text-transform:uppercase;letter-spacing:1.5px;">' + h + '</p>' + body + '</div>';
}

const headline = extract(digestText,'HEADLINE OF THE DAY');
const subject  = '\uD83D\uDCFA ' + (prev.today||'') + ' — AI+Tech Digest (' + prev.totalVideos + ' videos)';

const emailHtml = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>'
  + '<body style="margin:0;padding:0;background:#030712;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif;">'
  + '<div style="max-width:660px;margin:0 auto;padding:20px 0;">'
  + '<div style="background:linear-gradient(135deg,#1e1b4b,#312e81,#1e1b4b);padding:36px 32px;border-radius:14px 14px 0 0;text-align:center;">'
  + '<div style="font-size:44px;">\uD83D\uDCFA</div>'
  + '<h1 style="margin:8px 0 4px;color:#fff;font-size:22px;font-weight:900;">AI + Tech + Business Daily Digest</h1>'
  + '<p style="color:rgba(255,255,255,0.65);margin:0 0 14px;font-size:13px;">' + (prev.today||'') + '</p>'
  + '<span style="background:rgba(255,255,255,0.1);color:#a5b4fc;padding:4px 12px;border-radius:20px;font-size:11px;font-weight:700;">\uD83D\uDCF9 ' + prev.totalVideos + ' VIDEOS</span> '
  + '<span style="background:rgba(255,255,255,0.1);color:#fcd34d;padding:4px 12px;border-radius:20px;font-size:11px;font-weight:700;">\uD83D\uDD25 ' + trendingItems.length + ' TRENDING</span></div>'
  + (headline ? '<div style="background:#1f2937;border-left:4px solid #7c3aed;padding:16px 20px;"><p style="margin:0 0 4px;font-size:10px;font-weight:800;color:#7c3aed;text-transform:uppercase;letter-spacing:1.5px;">\uD83D\uDCA5 HEADLINE OF THE DAY</p><p style="margin:0;font-size:15px;color:#f9fafb;font-weight:700;line-height:1.5;">' + headline + '</p></div>' : '')
  + '<div style="background:#111827;padding:26px 30px;">'
  + (allVideos.length > 0 ? '<p style="margin:0 0 12px;font-size:10px;font-weight:800;color:#6366f1;text-transform:uppercase;letter-spacing:1.5px;">\uD83C\uDFC6 THIS WEEK ON YOUTUBE</p>' + videoCards : '')
  + block('\uD83D\uDCC4 VIDEO SUMMARIES', extract(digestText,'TOP VIDEOS THIS WEEK'),'#818cf8')
  + block('\uD83D\uDCA1 KEY INSIGHTS', extract(digestText,'KEY INSIGHTS'),'#34d399')
  + block('\uD83E\uDD16 AI & AUTOMATION', extract(digestText,'AI & AUTOMATION HIGHLIGHTS'),'#60a5fa')
  + block('\uD83D\uDCBC BUSINESS SIGNALS', extract(digestText,'BUSINESS & STARTUP SIGNALS'),'#f59e0b')
  + (trendingItems.length > 0 ? '<div style="margin-bottom:22px;"><p style="margin:0 0 10px;font-size:10px;font-weight:800;color:#f87171;text-transform:uppercase;letter-spacing:1.5px;">\uD83D\uDD25 TRENDING (TechCrunch + HN)</p>' + trendHtml + '</div>' : '')
  + block('\uD83D\uDD28 WHAT TO BUILD THIS WEEK', extract(digestText,'WHAT TO BUILD THIS WEEK'),'#a3e635')
  + (extract(digestText,'QUOTE OF THE DAY') ? '<div style="background:#1f2937;border:1px solid #374151;border-radius:10px;padding:18px;margin-bottom:20px;"><p style="margin:0 0 6px;font-size:10px;font-weight:800;color:#fbbf24;text-transform:uppercase;letter-spacing:1.5px;">\uD83D\uDDE8 QUOTE OF THE DAY</p><p style="margin:0;font-size:14px;color:#f3f4f6;font-style:italic;line-height:1.7;">' + extract(digestText,'QUOTE OF THE DAY') + '</p></div>' : '')
  + '</div>'
  + '<div style="background:#030712;padding:14px;text-align:center;border-radius:0 0 14px 14px;border-top:1px solid #1f2937;"><p style="color:#374151;font-size:10px;margin:0;">\uD83E\uDD16 JHD Advisor AI Digest &mdash; YouTube + TechCrunch + HN &mdash; Daily 8AM ET</p></div>'
  + '</div></body></html>';

console.log('[Email] ' + subject);
return [{ json: Object.assign({}, prev, { emailHtml, subject, digestText }) }];
